    cx = me.x + 0.7 * cos(h)
    cy = me.y + 0.7 * sin(h)
    rc = hypot(cx, cy)
    fwd = 1.0
    if rc > 5.8 and d > 1.6:
        err = bearing_to(0, 0)
        fwd = -0.8 if abs(err) > 90 else 0.6
    elif arena.time < 3.5 and rpm < 900 and d > 3:
        fwd = 0.0
    else:
        a = abs(err)
        if a > 45:
            fwd = 0.2
