def bounded(value, low, high):
    return max(low, min(high, value))

def jaw_overlap(me, enemy, prediction=0):
    mh = radians(me.heading)
    dx = enemy.x - me.x + (enemy.vx - me.vx) * prediction
    dy = enemy.y - me.y + (enemy.vy - me.vy) * prediction
    x = dx * cos(mh) + dy * sin(mh)
    y = -dx * sin(mh) + dy * cos(mh)

    relative = radians(enemy.heading - me.heading)
    ec = cos(relative)
    es = sin(relative)
    a = enemy.length * 0.5
    b = enemy.width * 0.5

    reach = me.weapons["front"]["reach"]
    x -= me.length * 0.5 + reach * 0.5
    fx = reach * 0.5 - 0.015
    fy = me.width * 0.4 - 0.015

    if abs(x) > fx + a * abs(ec) + b * abs(es):
        return False
    if abs(y) > fy + a * abs(es) + b * abs(ec):
        return False
    if abs(x * ec + y * es) > a + fx * abs(ec) + fy * abs(es):
        return False
    if abs(-x * es + y * ec) > b + fx * abs(es) + fy * abs(ec):
        return False
    return True

def aim_point(me, enemy):
    eh = radians(enemy.heading)
    ec = cos(eh)
    es = sin(eh)
    rotor = enemy.weapons.get("front")

    if rotor and rotor["type"] == "spinner":
        if rotor["health"] > 0:
            extension = enemy.length * 0.5 + rotor["radius"]
            return (enemy.x + ec * extension,
                    enemy.y + es * extension)

        dx = me.x - enemy.x
        dy = me.y - enemy.y
        distance = hypot(dx, dy)
        forward = dx * ec + dy * es
        sideways = -dx * es + dy * ec
        if distance < 3.2 and forward > 0.55 * distance:
            direction = me.memory.get("flank", 1)
            if abs(sideways) > 0.25:
                direction = 1 if sideways > 0 else -1
                me.memory["flank"] = direction
            offset = enemy.width * 0.5 + me.width * 0.5 + 0.2
            return (enemy.x - es * offset * direction,
                    enemy.y + ec * offset * direction)

    return (enemy.x, enemy.y)

def drive(me, enemy, arena):
    if not me.can_drive:
        return (0, 0)

    clamp = me.weapons["front"]
    holding = clamp["holding"]
    tx, ty = aim_point(me, enemy)
    distance = hypot(enemy.x - me.x, enemy.y - me.y)

    if holding:
        saved_heading = me.memory.get("hold_heading", me.heading)
        angle = (saved_heading - me.heading + 180) % 360 - 180
        desired_speed = 0.8
        radial = hypot(me.x, me.y)
        if radial > 4.8:
            mh = radians(me.heading)
            outward = me.x * cos(mh) + me.y * sin(mh)
            desired_speed = -0.9 if outward > 0 else 0.9
        desired_yaw = bounded(3.5 * angle, -100, 100)
    else:
        me.memory["hold_heading"] = me.heading
        angle = bearing_to(tx, ty)
        alignment = max(0, cos(radians(angle)))
        desired_speed = (3.6 if distance > 2.6 else 2.0)
        desired_speed *= alignment * alignment
        if abs(angle) > 65:
            desired_speed = 0
        desired_yaw = bounded(4.5 * angle, -230, 230)

        if clamp["state"] == "closing" and jaw_overlap(me, enemy):
            desired_speed = min(desired_speed, 0.8)
            desired_yaw = bounded(3.5 * bearing_to(enemy.x, enemy.y),
                                  -110, 110)

    if enemy.on_side and not enemy.airborne and not enemy.righting:
        angle = bearing_to(enemy.x, enemy.y)
        desired_yaw = bounded(3 * angle, -150, 150)
        desired_speed = 0
        if distance > 2.1:
            desired_speed = max(0, cos(radians(angle))) * 0.8
        elif distance < 1.6 and abs(angle) < 50:
            desired_speed = -0.7

    radial = hypot(me.x, me.y)
    if radial > 5.4:
        mh = radians(me.heading)
        outward = (me.x * cos(mh) + me.y * sin(mh)) / radial
        if desired_speed * outward > 0:
            limit = max(0.25, (6.0 - radial) * 2)
            desired_speed = bounded(desired_speed, -limit, limit)

    temperature = max(me.drive_left_temperature,
                      me.drive_right_temperature)
    effort_limit = 0.55
    if temperature > 105:
        effort_limit = bounded(0.45 - 0.008 * (temperature - 105),
                               0.12, 0.45)

    effort = bounded(0.43 * (desired_speed - me.speed),
                     -effort_limit, effort_limit)
    base = me.speed / 4.5 + effort
    turn = (radians(desired_yaw) * me.width / 9.0
            + 0.17 * radians(desired_yaw - me.turn_rate))
    turn = bounded(turn, -0.85, 0.85)

    left = base - turn
    right = base + turn
    scale = max(1, abs(left), abs(right))
    return (left / scale, right / scale)

def weapons(me, enemy, arena):
    if me.airborne or me.righting or me.on_side:
        return None

    clamp = me.weapons["front"]
    if clamp["health"] <= 0:
        return None

    if enemy.on_side and not enemy.airborne and not enemy.righting:
        if clamp["state"] != "open":
            return release("front")
        return None

    if clamp["holding"] or clamp["state"] == "closing":
        return None

    if clamp["state"] == "closed":
        return release("front")

    if clamp["cooldown"] <= 0 and not enemy.airborne:
        if jaw_overlap(me, enemy) or jaw_overlap(me, enemy, 0.3):
            return grab("front")

    return None
